-- CHRISTIAN iPad / Delta - available-assets version
-- Uses only the two files the user currently has:
--   download_57.png = main texture
--   ChatGPT_Image_25_Sky.jpg = available sky/texture image
-- Missing font, moon logos, and Black_colour.jpg are intentionally skipped.

local REPO = "https://raw.githubusercontent.com/lyn4x-js/I-pad-ez/main/"
local MAIN_URL = REPO .. "download_57.png"
local SKY_URL = nil -- embedded sky

local getcustom = getcustomasset or getsynasset
if not (writefile and getcustom) then
    warn("Christian pack: Delta file/custom-asset functions unavailable.")
    return
end

local function getAsset(url, filename)
    local ok, data = pcall(function()
        return game:HttpGet(url)
    end)
    if not ok or not data then
        warn("Christian pack download failed:", filename)
        return nil
    end

    local wrote = pcall(function()
        writefile(filename, data)
    end)
    if not wrote then
        warn("Christian pack write failed:", filename)
        return nil
    end

    local ok2, asset = pcall(function()
        return getcustom(filename)
    end)
    if ok2 then
        return asset
    end
    warn("Christian pack custom asset failed:", filename)
    return nil
end

-- Embedded cross/wings sky: no separate image file required
local SKY_B64 = ""

local function b64decode(data)
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    data = data:gsub("[^"..chars.."=]", "")
    return (data:gsub(".", function(x)
        if x == "=" then return "" end
        local r, f = "", chars:find(x, 1, true) - 1
        for i = 6, 1, -1 do
            r = r .. ((f % 2^i - f % 2^(i-1) > 0) and "1" or "0")
        end
        return r
    end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
        if #x ~= 8 then return "" end
        local c = 0
        for i = 1, 8 do
            if x:sub(i,i) == "1" then c = c + 2^(8-i) end
        end
        return string.char(c)
    end))
end

local skyAsset
if writefile and getcustom then
    local ok, result = pcall(function()
        local fn = "christian_cross_sky_embedded.jpeg"
        writefile(fn, b64decode(SKY_B64))
        return getcustom(fn)
    end)
    if ok then skyAsset = result else warn("Embedded Christian sky failed: "..tostring(result)) end
end

local mainAsset = getAsset(MAIN_URL, "christian_main.png")

local function applyChristianSky()
    if not skyAsset then return end
    local Lighting = game:GetService("Lighting")
    local sky = Lighting:FindFirstChildOfClass("Sky")
    if not sky then
        sky = Instance.new("Sky")
        sky.Name = "ChristianCrossSky"
        sky.Parent = Lighting
    end
    -- One supplied image is used on every face so the sky is complete.
    for _, prop in ipairs({"SkyboxBk","SkyboxDn","SkyboxFt","SkyboxLf","SkyboxRt","SkyboxUp"}) do
        pcall(function() sky[prop] = skyAsset end)
    end
end
applyChristianSky()


-- Mirc's 5K SFX
local mircKill1 = getAsset(
    "https://raw.githubusercontent.com/prism658/Resources-fleasion/main/kill1.ogg",
    "christian_mirc_kill1.ogg"
)
local mircKill2 = getAsset(
    "https://raw.githubusercontent.com/prism658/Resources-fleasion/main/kill2.ogg",
    "christian_mirc_kill2.ogg"
)
local mircKill3 = getAsset(
    "https://raw.githubusercontent.com/prism658/Resources-fleasion/main/kill3.ogg",
    "christian_mirc_kill3.ogg"
)
local mircSlide = getAsset(
    "https://raw.githubusercontent.com/prism658/Resources-fleasion/main/Sliding.mp3",
    "christian_mirc_slide.mp3"
)

local soundMap = {}
if mircKill1 then soundMap["16530229616"] = mircKill1 end
if mircKill2 then soundMap["16530229541"] = mircKill2 end
if mircKill3 then soundMap["16530229695"] = mircKill3 end
if mircSlide then soundMap["16737738420"] = mircSlide end

local idMap = {}

if mainAsset then
    idMap["7658055825"] = mainAsset
end

-- IDs assigned to the available ChatGPT sky image in the supplied JSON.
if skyAsset then
    local skyIds = {
        "14147882761",
        "12261809766",
        "135908632589654",
        "84214501374682",
        "10196550367",
        "2108482231",
    }
    for _, id in ipairs(skyIds) do
        idMap[id] = skyAsset
    end
end

local function extractId(value)
    if type(value) ~= "string" then return nil end
    return value:match("(%d+)")
end

local queue = {}
local head = 1

local function queueProperty(obj, prop)
    local ok, current = pcall(function()
        return obj[prop]
    end)
    if not ok or type(current) ~= "string" then return end

    local id = extractId(current)
    local replacement = id and idMap[id]
    if replacement then
        queue[#queue + 1] = {obj, prop, replacement}
    end
end

local function inspect(obj)
    if obj:IsA("Sound") then
        local ok, current = pcall(function() return obj.SoundId end)
        if ok and type(current) == "string" then
            local id = extractId(current)
            local replacement = id and soundMap[id]
            if replacement then
                pcall(function() obj.SoundId = replacement end)
            end
        end
    elseif obj:IsA("Texture") or obj:IsA("Decal") then
        queueProperty(obj, "Texture")
    elseif obj:IsA("MeshPart") then
        queueProperty(obj, "TextureID")
    elseif obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
        queueProperty(obj, "Image")
    end
end

task.spawn(function()
    local all = game:GetDescendants()
    for i, obj in ipairs(all) do
        inspect(obj)
        if i % 250 == 0 then
            task.wait()
        end
    end
end)

game:GetService("Lighting").ChildAdded:Connect(function(obj)
    if obj:IsA("Sky") then
        task.delay(0.15, applyChristianSky)
    end
end)

game.DescendantAdded:Connect(function(obj)
    task.defer(inspect, obj)
end)

task.spawn(function()
    while true do
        local n = 0
        while head <= #queue and n < 8 do
            local item = queue[head]
            head += 1
            n += 1

            local obj, prop, replacement = item[1], item[2], item[3]
            if obj and obj.Parent then
                pcall(function()
                    obj[prop] = replacement
                end)
            end
        end

        if head > 1000 and head > (#queue / 2) then
            local fresh = {}
            for i = head, #queue do
                fresh[#fresh + 1] = queue[i]
            end
            queue = fresh
            head = 1
        end

        task.wait(0.10)
    end
end)

print("Christian textures + cross sky + Mirc SFX loaded.")
